 1→import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
 2→import { Outlet, useLoaderData, useRouteError } from "react-router";
 3→import { boundary } from "@shopify/shopify-app-react-router/server";
 4→import { AppProvider } from "@shopify/shopify-app-react-router/react";
 5→
 6→import { authenticate } from "../shopify.server";
 7→
 8→export const loader = async ({ request }: LoaderFunctionArgs) => {
 9→  await authenticate.admin(request);
10→
11→  // eslint-disable-next-line no-undef
12→  return { apiKey: process.env.SHOPIFY_API_KEY || "" };
13→};
14→
15→export default function App() {
16→  const { apiKey } = useLoaderData<typeof loader>();
17→
18→  return (
19→    <AppProvider embedded apiKey={apiKey}>
20→      <s-app-nav>
21→        <s-link href="/app">Home</s-link>
22→        <s-link href="/app/additional">Additional page</s-link>
23→      </s-app-nav>
24→      <Outlet />
25→    </AppProvider>
26→  );
27→}
28→
29→// Shopify needs React Router to catch some thrown responses, so that their headers are included in the response.
30→export function ErrorBoundary() {
31→  return boundary.error(useRouteError());
32→}
33→
34→export const headers: HeadersFunction = (headersArgs) => {
35→  return boundary.headers(headersArgs);
