 1→import { PassThrough } from "stream";
 2→import { renderToPipeableStream } from "react-dom/server";
 3→import { ServerRouter } from "react-router";
 4→import { createReadableStreamFromReadable } from "@react-router/node";
 5→import { type EntryContext } from "react-router";
 6→import { isbot } from "isbot";
 7→import { addDocumentResponseHeaders } from "./shopify.server";
 8→
 9→export const streamTimeout = 5000;
10→
11→export default async function handleRequest(
12→  request: Request,
13→  responseStatusCode: number,
14→  responseHeaders: Headers,
15→  reactRouterContext: EntryContext
16→) {
17→  addDocumentResponseHeaders(request, responseHeaders);
18→  const userAgent = request.headers.get("user-agent");
19→  const callbackName = isbot(userAgent ?? '')
20→    ? "onAllReady"
21→    : "onShellReady";
22→
23→  return new Promise((resolve, reject) => {
24→    const { pipe, abort } = renderToPipeableStream(
25→      <ServerRouter
26→        context={reactRouterContext}
27→        url={request.url}
28→      />,
29→      {
30→        [callbackName]: () => {
31→          const body = new PassThrough();
32→          const stream = createReadableStreamFromReadable(body);
33→
34→          responseHeaders.set("Content-Type", "text/html");
35→          resolve(
36→            new Response(stream, {
37→              headers: responseHeaders,
38→              status: responseStatusCode,
39→            })
40→          );
41→          pipe(body);
42→        },
43→        onShellError(error) {
44→          reject(error);
45→        },
46→        onError(error) {
47→          responseStatusCode = 500;
48→          console.error(error);
49→        },
50→      }
51→    );
52→
53→    // Automatically timeout the React renderer after 6 seconds, which ensures
54→    // React has enough time to flush down the rejected boundary contents
55→    setTimeout(abort, streamTimeout + 1000);
56→  });
57→}
