 1→import type { ActionFunctionArgs } from "react-router";
 2→import { authenticate } from "../shopify.server";
 3→import db from "../db.server";
 4→
 5→export const action = async ({ request }: ActionFunctionArgs) => {
 6→  const { shop, session, topic } = await authenticate.webhook(request);
 7→
 8→  console.log(`Received ${topic} webhook for ${shop}`);
 9→
10→  // Webhook requests can trigger multiple times and after an app has already been uninstalled.
11→  // If this webhook already ran, the session may have been deleted previously.
12→  if (session) {
13→    await db.session.deleteMany({ where: { shop } });
14→  }
15→
16→  return new Response();
17→};
