 1→import type { ActionFunctionArgs } from "react-router";
 2→import { authenticate } from "../shopify.server";
 3→import db from "../db.server";
 4→
 5→export const action = async ({ request }: ActionFunctionArgs) => {
 6→    const { payload, session, topic, shop } = await authenticate.webhook(request);
 7→    console.log(`Received ${topic} webhook for ${shop}`);
 8→
 9→    const current = payload.current as string[];
10→    if (session) {
11→        await db.session.update({   
12→            where: {
13→                id: session.id
14→            },
15→            data: {
16→                scope: current.toString(),
17→            },
18→        });
19→    }
20→    return new Response();
21→};
